import time
import math
import sys
from sequential import build_tfidf_index_sequential, batch_search_sequential, load_corpus, generate_corpus
from parallel_solution import build_tfidf_index_parallel, batch_search_parallel
from document_generator import corpus_statistics

def compare_indices(idx1, idx2):
    if idx1.num_documents != idx2.num_documents:
        return False, f"num_documents mismatch: {idx1.num_documents} vs {idx2.num_documents}"

    if idx1.vocabulary != idx2.vocabulary:
        return False, "vocabulary mismatch"

    if idx1.document_frequencies != idx2.document_frequencies:
        return False, "document_frequencies mismatch"

    # Compare IDF
    for term in idx1.vocabulary:
        if not math.isclose(idx1.idf[term], idx2.idf[term], rel_tol=1e-9):
            return False, f"idf mismatch for term '{term}'"

    # Compare inverted_index
    if set(idx1.inverted_index.keys()) != set(idx2.inverted_index.keys()):
        return False, "inverted_index keys mismatch"

    for term in idx1.inverted_index:
        list1 = idx1.inverted_index[term]
        list2 = idx2.inverted_index[term]
        if len(list1) != len(list2):
            return False, f"inverted_index length mismatch for term '{term}'"
        for (d1, s1), (d2, s2) in zip(list1, list2):
            if d1 != d2 or not math.isclose(s1, s2, rel_tol=1e-9):
                return False, f"inverted_index content mismatch for term '{term}'"

    # Compare doc_norms
    if set(idx1.doc_norms.keys()) != set(idx2.doc_norms.keys()):
        return False, "doc_norms keys mismatch"
    for doc_id in idx1.doc_norms:
        if not math.isclose(idx1.doc_norms[doc_id], idx2.doc_norms[doc_id], rel_tol=1e-9):
            return False, f"doc_norms mismatch for doc_id {doc_id}"

    return True, "Indices are identical"

def compare_results(res1, res2):
    if len(res1) != len(res2):
        return False, "Number of queries mismatch"

    for i, (q_res1, q_res2) in enumerate(zip(res1, res2)):
        if len(q_res1) != len(q_res2):
            return False, f"Result length mismatch for query {i}"
        for r1, r2 in zip(q_res1, q_res2):
            if r1.doc_id != r2.doc_id or not math.isclose(r1.score, r2.score, rel_tol=1e-9):
                return False, f"Result content mismatch for query {i}: {r1} vs {r2}"

    return True, "Results are identical"

def main():
    num_docs = 2000
    print(f"Generating {num_docs} documents...")
    documents = generate_corpus(num_docs, seed=42)

    # Indexing
    print("\nBuilding Index Sequentially...")
    seq_idx_res = build_tfidf_index_sequential(documents)

    print("Building Index in Parallel (4 workers)...")
    par_idx_res = build_tfidf_index_parallel(documents, num_workers=4)

    identical, msg = compare_indices(seq_idx_res.index, par_idx_res.index)
    print(f"Index Identity Check: {msg}")
    if not identical:
        sys.exit(1)

    speedup_idx = seq_idx_res.elapsed_time / par_idx_res.elapsed_time
    print(f"Indexing Speedup: {speedup_idx:.2f}x")

    # Search
    queries = ["machine learning", "distributed systems", "data science", "network security", "cloud computing"] * 20
    print(f"\nPerforming Batch Search Sequentially ({len(queries)} queries)...")
    start_time = time.perf_counter()
    seq_search_res = batch_search_sequential(queries, seq_idx_res.index, top_k=10, documents=documents)
    seq_search_elapsed = time.perf_counter() - start_time

    print(f"Performing Batch Search in Parallel ({len(queries)} queries, 4 workers)...")
    par_search_res, par_search_elapsed = batch_search_parallel(queries, par_idx_res.index, top_k=10, num_workers=4, documents=documents)

    identical, msg = compare_results(seq_search_res, par_search_res)
    print(f"Search Results Identity Check: {msg}")
    if not identical:
        sys.exit(1)

    speedup_search = seq_search_elapsed / par_search_elapsed
    print(f"Search Speedup: {speedup_search:.2f}x")

    print("\nSummary:")
    print(f"Indexing Speedup Target: 1.5x, Achieved: {speedup_idx:.2f}x")
    print(f"Search Speedup Target: 2.0x, Achieved: {speedup_search:.2f}x")

if __name__ == "__main__":
    main()
